        cursor.execute(insert_sql, (new_pin))
        cursor.execute(id_sql)

        insert_data = cursor.fetchone()

        return jsonify({
            'id' : insert_data[0],
            'pin' : new_pin
        })
    except Exception as er_msg:
        return make_response(jsonify({
            'error' : str(er_msg)
        }), 500)
